Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9+7;
long long powerMod(long long a, long long b, long long mod) {
    long long res = 1, base = a;
    while(b) {
        if(b & 1) res = res * base % mod;
        base = base * base % mod;
        b >>= 1;
    }
    return res;
}
int main() {
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    int p, k;
    scanf("%d%d", &p, &k);
    int ans = 1;
    if(k == 0) {
        ans = powerMod(p, p-1, MOD);
        printf("%d\n", ans);
        return 0;
    }
    vector<bool> visited(p, false);
    vector<int> seq;
    for(int i = 0; i < p; ++i) {
        if(visited[i]) continue;
        int j = i;
        while(!visited[j]) {
            visited[j] = true;
            seq.push_back(j);
            j = (long long)j * k % p;
        }
        int d = seq.size();
        if(powerMod(k, d, p) == 1)
            ans = (long long)ans * p % MOD;
        seq.clear();
    }
    printf("%d\n", ans);
#ifndef ONLINE_JUDGE
    fclose(stdin); fclose(stdout);
#endif
    return 0;
}
</original_code>
